    #[test]
    fn test_generate_deprecated() {
        let _ = env_logger::try_init();
        let tempdir = tempfile::tempdir().unwrap();

        Config::new()
            .out_dir(tempdir.path())
            .compile_protos(
                &["src/fixtures/deprecated/all_deprecated.proto"],
                &["src/fixtures/deprecated"],
            )
            .unwrap();

        assert_eq_fixture_file!(
